package com.jsirgalaxybase.ui2.terminal;
import static org.junit.Assert.*;import java.util.*;import org.junit.Test;import com.jsirgalaxybase.ui2.core.*;import com.jsirgalaxybase.ui2.debug.UiDebugSnapshot;import com.jsirgalaxybase.ui2.motion.FixedUiClock;import com.jsirgalaxybase.ui2.theme.GlassTerminalTheme;
public class QuestMigrationPreviewVisualTest {
 @Test public void latestMigrationIsVisibleWithoutOverflowAtAllTerminalSizes(){TerminalVisualModel shell=new TerminalVisualModel("终端","career",Collections.singletonList(new TerminalVisualModel.NavItem("career","职业",true,true)));QuestManagementVisualModel model=new QuestManagementVisualModel(shell,"","","",0,20,0,Collections.<QuestManagementVisualModel.Definition>emptyList(),null,Collections.<QuestManagementVisualModel.ElementType>emptyList(),Collections.<QuestManagementVisualModel.ElementType>emptyList(),Collections.singletonList(new QuestManagementVisualModel.Migration("bq-0123456789abcdef","0123456789abcdef0123456789abcdef","PREVIEW",1L,128,7,42,2,3,"ERROR|UNSUPPORTED_TASK|quest|addon:special")));QuestManagementVisualDocument document=new QuestManagementVisualDocument(model,TerminalActionPort.NONE,QuestManagementActionPort.NONE,TerminalWindowProfile.STANDARD);for(int[] size:new int[][]{{350,193},{427,240},{620,340}}){UiRuntime runtime=new UiRuntime(document,new UiContext(GlassTerminalTheme.create(),Locale.CHINA,1F,new FixedUiClock(0,true)));runtime.setViewport(size[0],size[1]);String snapshot=UiDebugSnapshot.capture(runtime.getRoot(),runtime.frame(),size[0],size[1]);assertTrue(snapshot,snapshot.contains("PREVIEW"));assertTrue(snapshot,snapshot.contains("UNSUPPORTED_TASK"));assertTrue(snapshot,snapshot.contains("SUMMARY|issues=0"));runtime.close();}}
}
